-- Bone Data Manager — complete server setup.
-- Paste everything into Supabase → SQL Editor → Run, once, on a NEW project.
-- Generated by supabase/build_setup.py from supabase/migrations; do not edit by hand.

-- Bone Data Manager — cloud schema (Plan 2, Task 1)
-- Paste into Supabase → SQL Editor → Run. Safe to run once on an empty project.

-- ───────────────────────── Tables ─────────────────────────

create table public.databases (
  id                uuid primary key,
  name              text not null,
  prefix            text not null default '',
  digits            int  not null default 4 check (digits between 1 and 9),
  next_number       int  not null default 1,
  selected_elements jsonb not null default '[]',
  layers            jsonb not null default '[]',
  created_by        uuid default auth.uid(),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);

create table public.members (
  database_id uuid not null references public.databases(id) on delete cascade,
  email       text not null check (email = lower(email)),
  user_id     uuid,
  role        text not null check (role in ('owner', 'editor', 'viewer')),
  primary key (database_id, email)
);

create table public.entries (
  id          uuid primary key,
  database_id uuid not null references public.databases(id) on delete cascade,
  number      int  not null,
  ref_id      text not null,
  element_id  text not null,
  dentition   text,
  tooth_type  text,
  jaw         text,
  side        text,
  "values"    jsonb not null default '{}',
  created_by  text not null default '',
  created_at  timestamptz not null default now(),
  modified_by text not null default '',
  modified_at timestamptz not null default now(),
  version     int  not null default 1,
  deleted     boolean not null default false,
  updated_at  timestamptz not null default now(),
  unique (database_id, number),
  unique (database_id, ref_id)
);
create index entries_database_updated on public.entries (database_id, updated_at);

-- Numbers handed to a computer for offline work.
create table public.id_blocks (
  database_id  uuid not null references public.databases(id) on delete cascade,
  device_id    text not null,
  start_number int  not null,
  end_number   int  not null,
  primary key (database_id, device_id, start_number)
);

-- ───────────────────────── Helpers ─────────────────────────

-- The caller's role in a database (matched by user id or, for invitations, by email).
create or replace function public.my_role(db uuid) returns text
language sql stable security definer set search_path = public as $$
  select role from public.members
  where database_id = db
    and (user_id = auth.uid() or email = lower(coalesce(auth.jwt() ->> 'email', '')))
  order by case role when 'owner' then 0 when 'editor' then 1 else 2 end
  limit 1
$$;

create or replace function public._require(db uuid, allowed text[]) returns text
language plpgsql stable security definer set search_path = public as $$
declare r text := public.my_role(db);
begin
  if r is null or not (r = any (allowed)) then
    raise exception 'You do not have permission for this database' using errcode = '42501';
  end if;
  return r;
end $$;

-- 'MAS-' + 4 + 7 → 'MAS-0007'; numbers wider than digits are kept whole.
create or replace function public._ref(prefix text, digits int, n int) returns text
language sql immutable as $$
  select prefix || case when length(n::text) >= digits then n::text else lpad(n::text, digits, '0') end
$$;

-- A database must always keep at least one owner.
create or replace function public._keep_an_owner() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if exists (select 1 from public.databases where id = old.database_id)
     and not exists (select 1 from public.members where database_id = old.database_id and role = 'owner') then
    raise exception 'A database needs at least one owner' using errcode = '23514';
  end if;
  return null;
end $$;
create trigger members_keep_an_owner after update or delete on public.members
  for each row execute function public._keep_an_owner();

-- ───────────────────────── Row Level Security ─────────────────────────

alter table public.databases enable row level security;
alter table public.members   enable row level security;
alter table public.entries   enable row level security;
alter table public.id_blocks enable row level security;

create policy databases_read on public.databases for select to authenticated
  using (public.my_role(id) is not null);

create policy members_read on public.members for select to authenticated
  using (public.my_role(database_id) is not null);
create policy members_insert on public.members for insert to authenticated
  with check (public.my_role(database_id) = 'owner');
create policy members_update on public.members for update to authenticated
  using (public.my_role(database_id) = 'owner') with check (public.my_role(database_id) = 'owner');
create policy members_delete on public.members for delete to authenticated
  using (public.my_role(database_id) = 'owner');

create policy entries_read on public.entries for select to authenticated
  using (public.my_role(database_id) is not null);

-- databases, entries and id_blocks are written only through the functions below.
grant select on public.databases, public.entries, public.members to authenticated;
grant insert, update, delete on public.members to authenticated;

-- ───────────────────────── Functions (RPC) ─────────────────────────

-- New cloud database (wizard) or upload of a local one (Move to cloud). Idempotent for its owner.
create or replace function public.create_database(def jsonb, "rows" jsonb default '[]')
returns void language plpgsql security definer set search_path = public as $$
declare
  db   uuid := (def ->> 'id')::uuid;
  mail text := lower(coalesce(auth.jwt() ->> 'email', ''));
begin
  if auth.uid() is null then
    raise exception 'Sign in required' using errcode = '42501';
  end if;
  if exists (select 1 from public.databases where id = db) then
    perform public._require(db, array['owner']);
  else
    insert into public.databases (id, name, prefix, digits, next_number, selected_elements, layers, created_by)
    values (db, def ->> 'name', coalesce(def ->> 'prefix', ''), coalesce((def ->> 'digits')::int, 4),
            coalesce((def ->> 'next_number')::int, 1), coalesce(def -> 'selected_elements', '[]'),
            coalesce(def -> 'layers', '[]'), auth.uid());
    insert into public.members (database_id, email, user_id, role) values (db, mail, auth.uid(), 'owner');
  end if;

  insert into public.entries (id, database_id, number, ref_id, element_id, dentition, tooth_type, jaw, side,
                              "values", created_by, created_at, modified_by, modified_at, version, deleted)
  select r.id, db, r.number, r.ref_id, r.element_id, r.dentition, r.tooth_type, r.jaw, r.side,
         coalesce(r."values", '{}'), coalesce(r.created_by, ''), r.created_at, coalesce(r.modified_by, ''),
         r.modified_at, coalesce(r.version, 1), coalesce(r.deleted, false)
  from jsonb_to_recordset("rows") as r(id uuid, number int, ref_id text, element_id text, dentition text,
       tooth_type text, jaw text, side text, "values" jsonb, created_by text, created_at timestamptz,
       modified_by text, modified_at timestamptz, version int, deleted boolean)
  on conflict (id) do update
    set number = excluded.number, ref_id = excluded.ref_id, element_id = excluded.element_id,
        dentition = excluded.dentition, tooth_type = excluded.tooth_type, jaw = excluded.jaw,
        side = excluded.side, "values" = excluded."values", modified_by = excluded.modified_by,
        modified_at = excluded.modified_at, version = excluded.version, deleted = excluded.deleted,
        updated_at = now()
    where public.entries.database_id = db;

  update public.databases
  set next_number = greatest(next_number,
        coalesce((select max(number) + 1 from public.entries where database_id = db), 1))
  where id = db;
end $$;

-- Structure edits (owner). Never touches the counter.
create or replace function public.update_definition(db uuid, def jsonb)
returns void language plpgsql security definer set search_path = public as $$
begin
  perform public._require(db, array['owner']);
  update public.databases
  set name = def ->> 'name',
      prefix = coalesce(def ->> 'prefix', ''),
      digits = coalesce((def ->> 'digits')::int, 4),
      selected_elements = coalesce(def -> 'selected_elements', '[]'),
      layers = coalesce(def -> 'layers', '[]'),
      updated_at = now()
  where id = db;
end $$;

-- Online entry creation: the server hands out consecutive numbers atomically.
-- Each draft carries a client-chosen "id"; a retry after a lost response returns the same rows.
create or replace function public.create_entries(db uuid, drafts jsonb, observer text)
returns setof public.entries language plpgsql security definer set search_path = public as $$
declare
  n       int := jsonb_array_length(drafts);
  start_n int;
  p       text;
  dg      int;
  ids     uuid[];
begin
  perform public._require(db, array['owner', 'editor']);
  select array_agg((v ->> 'id')::uuid) into ids
  from jsonb_array_elements(drafts) v where v ? 'id';

  if ids is not null and array_length(ids, 1) = n
     and (select count(*) from public.entries where database_id = db and id = any (ids)) = n then
    return query select * from public.entries where database_id = db and id = any (ids) order by number;
    return;
  end if;

  update public.databases set next_number = next_number + n
  where id = db
  returning next_number - n, prefix, digits into start_n, p, dg;

  return query
  insert into public.entries (id, database_id, number, ref_id, element_id, dentition, tooth_type, jaw, side,
                              "values", created_by, created_at, modified_by, modified_at, version, deleted)
  select coalesce((d.v ->> 'id')::uuid, gen_random_uuid()), db, start_n + (d.ord - 1)::int,
         public._ref(p, dg, start_n + (d.ord - 1)::int),
         d.v ->> 'element_id', d.v ->> 'dentition', d.v ->> 'tooth_type', d.v ->> 'jaw', d.v ->> 'side',
         coalesce(d.v -> 'values', '{}'), observer, now(), observer, now(), 1, false
  from jsonb_array_elements(drafts) with ordinality as d(v, ord)
  on conflict (id) do nothing
  returning *;
end $$;

-- Offline numbers: takes `size` numbers from the counter for one computer.
create or replace function public.reserve_block(db uuid, device text, size int)
returns table (block_start int, block_end int)
language plpgsql security definer set search_path = public as $$
declare s int;
begin
  perform public._require(db, array['owner', 'editor']);
  if size is null or size < 1 or size > 1000 then
    raise exception 'Block size must be between 1 and 1000' using errcode = '22023';
  end if;
  update public.databases set next_number = next_number + size
  where id = db
  returning next_number - size into s;
  insert into public.id_blocks (database_id, device_id, start_number, end_number)
  values (db, device, s, s + size - 1);
  block_start := s;
  block_end := s + size - 1;
  return next;
end $$;

-- Upload one entry created or changed on a computer.
-- New id: inserted (its number must come from a reserved block).
-- Existing id: updated only if nobody changed it since `base_version`; otherwise returns the server row.
-- base_version 0 means "created on this computer": it matches the server's first version (an online
-- create whose answer was lost). A retry of a change the server already has is answered as ok.
create or replace function public.push_entry(db uuid, e jsonb, base_version int)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  eid uuid := (e ->> 'id')::uuid;
  num int  := (e ->> 'number')::int;
  cur public.entries;
  v   int;
begin
  perform public._require(db, array['owner', 'editor']);
  select * into cur from public.entries where id = eid and database_id = db for update;

  if not found then
    if not exists (select 1 from public.id_blocks b
                   where b.database_id = db and num between b.start_number and b.end_number) then
      raise exception 'Number % was not reserved for offline use', num using errcode = '22023';
    end if;
    insert into public.entries (id, database_id, number, ref_id, element_id, dentition, tooth_type, jaw, side,
                                "values", created_by, created_at, modified_by, modified_at, version, deleted)
    values (eid, db, num, e ->> 'ref_id', e ->> 'element_id', e ->> 'dentition', e ->> 'tooth_type',
            e ->> 'jaw', e ->> 'side', coalesce(e -> 'values', '{}'), coalesce(e ->> 'created_by', ''),
            (e ->> 'created_at')::timestamptz, coalesce(e ->> 'modified_by', ''),
            (e ->> 'modified_at')::timestamptz, 1, coalesce((e ->> 'deleted')::boolean, false));
    return jsonb_build_object('status', 'ok', 'version', 1);
  end if;

  if base_version = 0 then
    base_version := 1;
  end if;
  if cur.version <> base_version then
    if cur.element_id is not distinct from e ->> 'element_id'
       and cur.dentition is not distinct from e ->> 'dentition'
       and cur.tooth_type is not distinct from e ->> 'tooth_type'
       and cur.jaw is not distinct from e ->> 'jaw'
       and cur.side is not distinct from e ->> 'side'
       and cur."values" = coalesce(e -> 'values', '{}')
       and cur.deleted = coalesce((e ->> 'deleted')::boolean, false) then
      return jsonb_build_object('status', 'ok', 'version', cur.version);
    end if;
    return jsonb_build_object('status', 'conflict', 'row', to_jsonb(cur));
  end if;

  update public.entries
  set element_id = e ->> 'element_id', dentition = e ->> 'dentition', tooth_type = e ->> 'tooth_type',
      jaw = e ->> 'jaw', side = e ->> 'side', "values" = coalesce(e -> 'values', '{}'),
      modified_by = coalesce(e ->> 'modified_by', ''), modified_at = (e ->> 'modified_at')::timestamptz,
      deleted = coalesce((e ->> 'deleted')::boolean, false),
      version = cur.version + 1, updated_at = now()
  where id = eid
  returning version into v;
  return jsonb_build_object('status', 'ok', 'version', v);
end $$;

-- Only signed-in users may call the functions.
revoke execute on function public.create_database(jsonb, jsonb), public.update_definition(uuid, jsonb),
  public.create_entries(uuid, jsonb, text), public.reserve_block(uuid, text, int),
  public.push_entry(uuid, jsonb, int), public.my_role(uuid) from public, anon;
grant execute on function public.create_database(jsonb, jsonb), public.update_definition(uuid, jsonb),
  public.create_entries(uuid, jsonb, text), public.reserve_block(uuid, text, int),
  public.push_entry(uuid, jsonb, int), public.my_role(uuid) to authenticated;
revoke execute on function public._require(uuid, text[]), public._ref(text, int, int) from public, anon;

-- ───────────────────────── Realtime ─────────────────────────

alter publication supabase_realtime add table public.entries, public.databases;

-- Bone Data Manager — shared Ref IDs for teeth (spec §18). Run after 001_init.sql.

-- A Ref ID may now be shared by several rows; one element appears once per ID among live rows.
alter table public.entries drop constraint if exists entries_database_id_number_key;
alter table public.entries drop constraint if exists entries_database_id_ref_id_key;
do $$
begin
  if exists (select 1 from pg_constraint where conrelid = 'public.entries'::regclass and contype = 'u') then
    raise exception 'entries still has a UNIQUE constraint on number or ref_id; drop it, then rerun this file';
  end if;
end $$;
create unique index if not exists entries_one_element_per_id on public.entries
  (database_id, number, element_id, coalesce(dentition, ''), coalesce(tooth_type, ''),
   coalesce(jaw, ''), coalesce(side, ''))
  where not deleted;

-- create_entries gains `shared`: all drafts get one number.
drop function if exists public.create_entries(uuid, jsonb, text);
create or replace function public.create_entries(db uuid, drafts jsonb, observer text, shared boolean default false)
returns setof public.entries language plpgsql security definer set search_path = public as $$
declare
  n       int := jsonb_array_length(drafts);
  start_n int;
  p       text;
  dg      int;
  ids     uuid[];
begin
  perform public._require(db, array['owner', 'editor']);
  select array_agg((v ->> 'id')::uuid) into ids
  from jsonb_array_elements(drafts) v where v ? 'id';

  if ids is not null and array_length(ids, 1) = n
     and (select count(*) from public.entries where database_id = db and id = any (ids)) = n then
    return query select * from public.entries where database_id = db and id = any (ids) order by number;
    return;
  end if;

  update public.databases set next_number = next_number + case when shared then 1 else n end
  where id = db
  returning next_number - case when shared then 1 else n end, prefix, digits into start_n, p, dg;

  return query
  insert into public.entries (id, database_id, number, ref_id, element_id, dentition, tooth_type, jaw, side,
                              "values", created_by, created_at, modified_by, modified_at, version, deleted)
  select coalesce((d.v ->> 'id')::uuid, gen_random_uuid()), db,
         start_n + case when shared then 0 else (d.ord - 1)::int end,
         public._ref(p, dg, start_n + case when shared then 0 else (d.ord - 1)::int end),
         d.v ->> 'element_id', d.v ->> 'dentition', d.v ->> 'tooth_type', d.v ->> 'jaw', d.v ->> 'side',
         coalesce(d.v -> 'values', '{}'), observer, now(), observer, now(), 1, false
  from jsonb_array_elements(drafts) with ordinality as d(v, ord)
  on conflict (id) do nothing
  returning *;
end $$;
revoke execute on function public.create_entries(uuid, jsonb, text, boolean) from public, anon;
grant execute on function public.create_entries(uuid, jsonb, text, boolean) to authenticated;

-- push_entry: a new row may join an existing Ref ID ("Add teeth to …", also offline).
create or replace function public.push_entry(db uuid, e jsonb, base_version int)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  eid uuid := (e ->> 'id')::uuid;
  num int  := (e ->> 'number')::int;
  cur public.entries;
  dup public.entries;
  v   int;
begin
  perform public._require(db, array['owner', 'editor']);
  select * into cur from public.entries where id = eid and database_id = db for update;

  if not found then
    -- A new row's number comes from a reserved block, or joins an existing (shared) Ref ID.
    if not exists (select 1 from public.id_blocks b
                   where b.database_id = db and num between b.start_number and b.end_number)
       and not exists (select 1 from public.entries x where x.database_id = db and x.number = num) then
      raise exception 'Number % was not reserved for offline use', num using errcode = '22023';
    end if;
    begin
      insert into public.entries (id, database_id, number, ref_id, element_id, dentition, tooth_type, jaw, side,
                                  "values", created_by, created_at, modified_by, modified_at, version, deleted)
      values (eid, db, num, e ->> 'ref_id', e ->> 'element_id', e ->> 'dentition', e ->> 'tooth_type',
              e ->> 'jaw', e ->> 'side', coalesce(e -> 'values', '{}'), coalesce(e ->> 'created_by', ''),
              (e ->> 'created_at')::timestamptz, coalesce(e ->> 'modified_by', ''),
              (e ->> 'modified_at')::timestamptz, 1, coalesce((e ->> 'deleted')::boolean, false));
    exception when unique_violation then
      -- The same tooth was added to this Ref ID from another device.
      select * into dup from public.entries x
      where x.database_id = db and x.number = num and not x.deleted and x.id <> eid
        and x.element_id is not distinct from e ->> 'element_id' and x.dentition is not distinct from e ->> 'dentition'
        and x.tooth_type is not distinct from e ->> 'tooth_type' and x.jaw is not distinct from e ->> 'jaw'
        and x.side is not distinct from e ->> 'side'
      limit 1;
      return jsonb_build_object('status', 'duplicate', 'row', to_jsonb(dup));
    end;
    return jsonb_build_object('status', 'ok', 'version', 1);
  end if;

  if base_version = 0 then
    base_version := 1;
  end if;
  if cur.version <> base_version then
    if cur.element_id is not distinct from e ->> 'element_id'
       and cur.dentition is not distinct from e ->> 'dentition'
       and cur.tooth_type is not distinct from e ->> 'tooth_type'
       and cur.jaw is not distinct from e ->> 'jaw'
       and cur.side is not distinct from e ->> 'side'
       and cur."values" = coalesce(e -> 'values', '{}')
       and cur.deleted = coalesce((e ->> 'deleted')::boolean, false) then
      return jsonb_build_object('status', 'ok', 'version', cur.version);
    end if;
    return jsonb_build_object('status', 'conflict', 'row', to_jsonb(cur));
  end if;

  begin
    update public.entries
    set element_id = e ->> 'element_id', dentition = e ->> 'dentition', tooth_type = e ->> 'tooth_type',
        jaw = e ->> 'jaw', side = e ->> 'side', "values" = coalesce(e -> 'values', '{}'),
        modified_by = coalesce(e ->> 'modified_by', ''), modified_at = (e ->> 'modified_at')::timestamptz,
        deleted = coalesce((e ->> 'deleted')::boolean, false),
        version = cur.version + 1, updated_at = now()
    where id = eid
    returning version into v;
  exception when unique_violation then
    -- The edit turns this row into a tooth another row already holds under the same Ref ID.
    select * into dup from public.entries x
    where x.database_id = db and x.number = cur.number and not x.deleted and x.id <> eid
      and x.element_id is not distinct from e ->> 'element_id' and x.dentition is not distinct from e ->> 'dentition'
      and x.tooth_type is not distinct from e ->> 'tooth_type' and x.jaw is not distinct from e ->> 'jaw'
      and x.side is not distinct from e ->> 'side'
    limit 1;
    return jsonb_build_object('status', 'duplicate', 'row', to_jsonb(dup));
  end;
  return jsonb_build_object('status', 'ok', 'version', v);
end $$;

-- Bone Data Manager — lets the app check which setup a server has (Connect → Test connection).
-- Safe on servers that already ran 001 and 002: it only adds a function.
create or replace function public.app_schema_version() returns int
language sql immutable as $$ select 3 $$;
grant execute on function public.app_schema_version() to anon, authenticated;

-- Bone Data Manager — gapless Ref IDs: offline entries get provisional (TEMP) numbers that claim a real
-- number on sync, the Owner can close gaps ("Close Ref ID gaps"), and a numbering epoch tells devices
-- that numbers changed. Safe to run after 001–003. Replaces reserved offline blocks (id_blocks).

-- ───────────────────────── Schema ─────────────────────────

alter table public.entries add column if not exists previous_ref_ids jsonb not null default '[]';
alter table public.databases add column if not exists numbering_epoch int not null default 0;

-- Real numbers given to provisional groups. A retried claim (lost answer) gets the same number back.
-- `ids` are the group's entry ids: while none of them is uploaded, the claim keeps its number live.
create table if not exists public.temp_claims (
  database_id uuid not null references public.databases(id) on delete cascade,
  device_id   text not null,
  temp_number int  not null,
  number      int  not null,
  ids         uuid[] not null default '{}',
  primary key (database_id, device_id, temp_number)
);
alter table public.temp_claims enable row level security;
drop policy if exists temp_claims_read on public.temp_claims;
create policy temp_claims_read on public.temp_claims for select to authenticated
  using (public.my_role(database_id) is not null);
-- temp_claims is written only through the functions below.
grant select on public.temp_claims to authenticated;

-- Reserved blocks are no longer used.
drop function if exists public.reserve_block(uuid, text, int);
drop table if exists public.id_blocks;

-- ───────────────────────── Functions (RPC) ─────────────────────────

-- The real number for provisional group `temp` of `device`. `ids` are the group's entry ids: if one of
-- them already reached the server (an online create whose answer was lost), its number is reused and
-- `temp_ref` (the TEMP Ref ID the user saw) is added to those rows' previous_ref_ids, so no ID is lost.
drop function if exists public.claim_number(uuid, text, int, uuid[]);
create or replace function public.claim_number(db uuid, device text, temp int, ids uuid[], temp_ref text default null)
returns int language plpgsql security definer set search_path = public as $$
declare
  n int;
begin
  perform public._require(db, array['owner', 'editor']);
  -- One claim at a time per database, and never during compact_ref_ids.
  perform 1 from public.databases d where d.id = db for no key update;

  select c.number into n from public.temp_claims c
  where c.database_id = db and c.device_id = device and c.temp_number = temp;
  if found then
    return n;
  end if;

  select x.number into n from public.entries x
  where x.database_id = db and x.id = any (claim_number.ids)
  order by x.deleted, x.number
  limit 1;
  if not found then
    update public.databases d set next_number = d.next_number + 1
    where d.id = db
    returning d.next_number - 1 into n;
  elsif temp_ref is not null then
    -- Bumps updated_at (devices pull it) but not version (no conflict with pending edits).
    update public.entries x
    set previous_ref_ids = x.previous_ref_ids || jsonb_build_array(temp_ref), updated_at = now()
    where x.database_id = db and x.id = any (claim_number.ids) and not (x.previous_ref_ids ? temp_ref);
  end if;

  insert into public.temp_claims (database_id, device_id, temp_number, number, ids)
  values (db, device, temp, n, coalesce(claim_number.ids, '{}'));
  return n;
end $$;

-- Close Ref ID gaps (Owner): live numbers become 1, 2, 3… in order. A changed row keeps its old Ref ID
-- in previous_ref_ids; its version is not bumped, so pending edits on devices do not conflict.
-- Returns {"epoch": n, "changes": [{id, number, ref_id, previous_ref_ids}, …]}.
create or replace function public.compact_ref_ids(db uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  p         text;
  dg        int;
  cur_epoch int;
  k         int;
  olds      int[];
  news      int[];
  changes   jsonb;
begin
  perform public._require(db, array['owner']);
  -- Waits for running pushes and claims; new ones wait until this finishes.
  select d.prefix, d.digits, d.numbering_epoch into p, dg, cur_epoch
  from public.databases d where d.id = db for update;

  if exists (select 1 from public.entries x where x.database_id = db and not x.deleted and x.number < 1) then
    raise exception 'Some entries have an invalid Ref ID number' using errcode = '22023';
  end if;

  -- Live numbers: those of live entries, plus claims none of whose entries is uploaded yet (a claim
  -- without ids: no entry holds its number). A pending claim stays live even if a deleted row has its number.
  with live as (
    select x.number from public.entries x where x.database_id = db and not x.deleted
    union
    select c.number from public.temp_claims c
    where c.database_id = db
      and case when cardinality(c.ids) > 0
               then not exists (select 1 from public.entries y where y.database_id = db and y.id = any (c.ids))
               else not exists (select 1 from public.entries y where y.database_id = db and y.number = c.number)
          end
  ), m as (
    select l.number as old_n, (row_number() over (order by l.number))::int as new_n from live l
  )
  select count(*)::int,
         coalesce(array_agg(m.old_n order by m.old_n) filter (where m.old_n <> m.new_n), '{}'),
         coalesce(array_agg(m.new_n order by m.old_n) filter (where m.old_n <> m.new_n), '{}')
  into k, olds, news
  from m;

  update public.databases d set next_number = k + 1 where d.id = db;

  if cardinality(olds) = 0 then
    return jsonb_build_object('epoch', cur_epoch, 'changes', '[]'::jsonb);
  end if;

  -- Two phases so no row lands on a number another live row still holds (entries_one_element_per_id).
  -- Phase 1: changed rows go negative (live numbers are all positive, so negatives are free).
  update public.entries x set number = -x.number
  where x.database_id = db and not x.deleted and x.number = any (olds);

  -- Phase 2: final numbers; the old Ref ID is kept.
  with u as (
    update public.entries x
    set number = m.new_n,
        ref_id = public._ref(p, dg, m.new_n),
        previous_ref_ids = x.previous_ref_ids || to_jsonb(x.ref_id),
        updated_at = now()
    from unnest(olds, news) as m(old_n, new_n)
    where x.database_id = db and not x.deleted and x.number = -m.old_n
    returning x.id, x.number, x.ref_id, x.previous_ref_ids
  )
  select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'number', u.number, 'ref_id', u.ref_id,
                                               'previous_ref_ids', u.previous_ref_ids)
                            order by u.number, u.id), '[]'::jsonb)
  into changes
  from u;

  -- A repeated claim must return the group's current number.
  update public.temp_claims c set number = m.new_n
  from unnest(olds, news) as m(old_n, new_n)
  where c.database_id = db and c.number = m.old_n;

  update public.databases d set numbering_epoch = d.numbering_epoch + 1
  where d.id = db
  returning d.numbering_epoch into cur_epoch;

  return jsonb_build_object('epoch', cur_epoch, 'changes', changes);
end $$;

-- create_database (from 001) also uploads previous_ref_ids ("Move to cloud" of a compacted database),
-- and locks the database row before touching entries, like the other functions.
create or replace function public.create_database(def jsonb, "rows" jsonb default '[]')
returns void language plpgsql security definer set search_path = public as $$
declare
  db   uuid := (def ->> 'id')::uuid;
  mail text := lower(coalesce(auth.jwt() ->> 'email', ''));
begin
  if auth.uid() is null then
    raise exception 'Sign in required' using errcode = '42501';
  end if;
  if exists (select 1 from public.databases where id = db) then
    perform public._require(db, array['owner']);
  else
    insert into public.databases (id, name, prefix, digits, next_number, selected_elements, layers, created_by)
    values (db, def ->> 'name', coalesce(def ->> 'prefix', ''), coalesce((def ->> 'digits')::int, 4),
            coalesce((def ->> 'next_number')::int, 1), coalesce(def -> 'selected_elements', '[]'),
            coalesce(def -> 'layers', '[]'), auth.uid());
    insert into public.members (database_id, email, user_id, role) values (db, mail, auth.uid(), 'owner');
  end if;
  perform 1 from public.databases d where d.id = db for no key update;

  insert into public.entries (id, database_id, number, ref_id, element_id, dentition, tooth_type, jaw, side,
                              "values", created_by, created_at, modified_by, modified_at, version, deleted,
                              previous_ref_ids)
  select r.id, db, r.number, r.ref_id, r.element_id, r.dentition, r.tooth_type, r.jaw, r.side,
         coalesce(r."values", '{}'), coalesce(r.created_by, ''), r.created_at, coalesce(r.modified_by, ''),
         r.modified_at, coalesce(r.version, 1), coalesce(r.deleted, false), coalesce(r.previous_ref_ids, '[]')
  from jsonb_to_recordset("rows") as r(id uuid, number int, ref_id text, element_id text, dentition text,
       tooth_type text, jaw text, side text, "values" jsonb, created_by text, created_at timestamptz,
       modified_by text, modified_at timestamptz, version int, deleted boolean, previous_ref_ids jsonb)
  on conflict (id) do update
    set number = excluded.number, ref_id = excluded.ref_id, element_id = excluded.element_id,
        dentition = excluded.dentition, tooth_type = excluded.tooth_type, jaw = excluded.jaw,
        side = excluded.side, "values" = excluded."values", modified_by = excluded.modified_by,
        modified_at = excluded.modified_at, version = excluded.version, deleted = excluded.deleted,
        previous_ref_ids = excluded.previous_ref_ids, updated_at = now()
    where public.entries.database_id = db;

  update public.databases
  set next_number = greatest(next_number,
        coalesce((select max(number) + 1 from public.entries where database_id = db), 1))
  where id = db;
end $$;

-- push_entry gains `epoch`: the numbering_epoch the device knows. The old 3-argument version is
-- removed on purpose, so an outdated app cannot upload numbers that may have changed.
-- New id: inserted if its number was claimed (temp_claims) or joins a live Ref ID; if numbers
-- changed since the device's epoch, returns {"status": "stale"} so the device renumbers and retries.
-- Existing id: as before; an update never touches number, ref_id or previous_ref_ids.
drop function if exists public.push_entry(uuid, jsonb, int);
create or replace function public.push_entry(db uuid, e jsonb, base_version int, epoch int)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  eid       uuid := (e ->> 'id')::uuid;
  num       int  := (e ->> 'number')::int;
  cur_epoch int;
  cur       public.entries;
  dup       public.entries;
  v         int;
begin
  perform public._require(db, array['owner', 'editor']);
  -- Never runs alongside compact_ref_ids (which locks this row for update); pushes do not block each other.
  select d.numbering_epoch into cur_epoch from public.databases d where d.id = db for key share;
  select * into cur from public.entries x where x.id = eid and x.database_id = db for update;

  if not found then
    if epoch is distinct from cur_epoch then
      return jsonb_build_object('status', 'stale');
    end if;
    -- A new row's number was claimed, or it joins an existing (shared) Ref ID that is still live: a
    -- number held only by deleted rows may be reused by compaction for another specimen.
    if not exists (select 1 from public.temp_claims c where c.database_id = db and c.number = num)
       and not exists (select 1 from public.entries x where x.database_id = db and x.number = num
                       and not x.deleted) then
      raise exception 'Number % was not claimed', num using errcode = '22023';
    end if;
    begin
      insert into public.entries (id, database_id, number, ref_id, element_id, dentition, tooth_type, jaw, side,
                                  "values", created_by, created_at, modified_by, modified_at, version, deleted,
                                  previous_ref_ids)
      values (eid, db, num, e ->> 'ref_id', e ->> 'element_id', e ->> 'dentition', e ->> 'tooth_type',
              e ->> 'jaw', e ->> 'side', coalesce(e -> 'values', '{}'), coalesce(e ->> 'created_by', ''),
              (e ->> 'created_at')::timestamptz, coalesce(e ->> 'modified_by', ''),
              (e ->> 'modified_at')::timestamptz, 1, coalesce((e ->> 'deleted')::boolean, false),
              case when jsonb_typeof(e -> 'previous_ref_ids') = 'array' then e -> 'previous_ref_ids'
                   else '[]'::jsonb end);
    exception when unique_violation then
      -- The same tooth was added to this Ref ID from another device.
      select * into dup from public.entries x
      where x.database_id = db and x.number = num and not x.deleted and x.id <> eid
        and x.element_id is not distinct from e ->> 'element_id' and x.dentition is not distinct from e ->> 'dentition'
        and x.tooth_type is not distinct from e ->> 'tooth_type' and x.jaw is not distinct from e ->> 'jaw'
        and x.side is not distinct from e ->> 'side'
      limit 1;
      return jsonb_build_object('status', 'duplicate', 'row', to_jsonb(dup));
    end;
    return jsonb_build_object('status', 'ok', 'version', 1);
  end if;

  if base_version = 0 then
    base_version := 1;
  end if;
  if cur.version <> base_version then
    if cur.element_id is not distinct from e ->> 'element_id'
       and cur.dentition is not distinct from e ->> 'dentition'
       and cur.tooth_type is not distinct from e ->> 'tooth_type'
       and cur.jaw is not distinct from e ->> 'jaw'
       and cur.side is not distinct from e ->> 'side'
       and cur."values" = coalesce(e -> 'values', '{}')
       and cur.deleted = coalesce((e ->> 'deleted')::boolean, false) then
      return jsonb_build_object('status', 'ok', 'version', cur.version);
    end if;
    return jsonb_build_object('status', 'conflict', 'row', to_jsonb(cur));
  end if;

  begin
    update public.entries x
    set element_id = e ->> 'element_id', dentition = e ->> 'dentition', tooth_type = e ->> 'tooth_type',
        jaw = e ->> 'jaw', side = e ->> 'side', "values" = coalesce(e -> 'values', '{}'),
        modified_by = coalesce(e ->> 'modified_by', ''), modified_at = (e ->> 'modified_at')::timestamptz,
        deleted = coalesce((e ->> 'deleted')::boolean, false),
        version = cur.version + 1, updated_at = now()
    where x.id = eid
    returning x.version into v;
  exception when unique_violation then
    -- The edit turns this row into a tooth another row already holds under the same Ref ID.
    select * into dup from public.entries x
    where x.database_id = db and x.number = cur.number and not x.deleted and x.id <> eid
      and x.element_id is not distinct from e ->> 'element_id' and x.dentition is not distinct from e ->> 'dentition'
      and x.tooth_type is not distinct from e ->> 'tooth_type' and x.jaw is not distinct from e ->> 'jaw'
      and x.side is not distinct from e ->> 'side'
    limit 1;
    return jsonb_build_object('status', 'duplicate', 'row', to_jsonb(dup));
  end;
  return jsonb_build_object('status', 'ok', 'version', v);
end $$;

-- Only signed-in users may call the functions.
revoke execute on function public.claim_number(uuid, text, int, uuid[], text), public.compact_ref_ids(uuid),
  public.push_entry(uuid, jsonb, int, int) from public, anon;
grant execute on function public.claim_number(uuid, text, int, uuid[], text), public.compact_ref_ids(uuid),
  public.push_entry(uuid, jsonb, int, int) to authenticated;

-- The app expects this setup.
create or replace function public.app_schema_version() returns int
language sql immutable as $$ select 4 $$;
grant execute on function public.app_schema_version() to anon, authenticated;
